const nav=document.querySelector('#navigation'),toggle=document.querySelector('.menu-toggle'),dialog=document.querySelector('#detail');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open);if(open)closeSolutionsMenu()});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});function show(title,body,label='EXPLORE GRIIDAI'){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').textContent=body;document.querySelector('#dialog-label').textContent=label;dialog.showModal()}document.querySelectorAll('.close,.close-bottom').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});const workflowData=[["DEM Hydrology & Stream Network", "Turn elevation data into drainage and stream-network analysis."], ["NDVI Analysis", "Use satellite imagery to examine vegetation condition."], ["Fire Station Coverage", "Identify service coverage and areas that may be underserved."], ["Sea-Level Rise", "Explore how different water-level scenarios affect exposed locations."], ["Storm Surge", "Analyze coastal exposure under storm-surge conditions."]];document.querySelectorAll('[data-workflow]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const item=workflowData[Number(a.dataset.workflow)];show(item[0],item[1],'WORKFLOW EXAMPLE')}));document.querySelectorAll('.modal-link').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();show('The GriidAi ecosystem','Contribute: build tools and workflows. Educate: use GriidAi in teaching and research. Grow: build communities, training and awareness. Deliver: bring geospatial solutions to organizations.')}));window.griidaiEvents=[];document.addEventListener('click',e=>{const a=e.target.closest('a');if(a)window.griidaiEvents.push({event:'homepage_link_click',label:a.textContent.trim(),destination:a.getAttribute('href')})});
const solutionsMenuButton=document.querySelector('.solutions-menu-toggle'),solutionsSubmenu=document.querySelector('#solutions-submenu');function closeSolutionsMenu(){solutionsSubmenu.hidden=true;solutionsMenuButton.setAttribute('aria-expanded','false')}solutionsMenuButton.addEventListener('click',()=>{const open=solutionsMenuButton.getAttribute('aria-expanded')==='true';solutionsSubmenu.hidden=open;solutionsMenuButton.setAttribute('aria-expanded',String(!open))});document.addEventListener('click',e=>{if(!e.target.closest('.solutions-nav-group'))closeSolutionsMenu()});document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(!solutionsSubmenu.hidden){closeSolutionsMenu();solutionsMenuButton.focus()}else if(nav.classList.contains('open')){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.focus()}});solutionsSubmenu.addEventListener('click',e=>{if(e.target.closest('a'))closeSolutionsMenu()});
